# region Command.update_role
router = APIRouter(prefix="/auth")

class UpdateRoleRequest(BaseModel):
    requester_id: UUID = Field(..., description="ID của tài khoản yêu cầu thay đổi quyền")
    target_user_id: UUID = Field(..., description="ID của tài khoản cần phân quyền")
    new_role: str = Field(..., description="Tên quyền mới cần thay đổi")

class UpdateRoleResponse(BaseModel):
    user_id: UUID = Field(..., description="ID của user đã được cập nhật role")
    role: str = Field(..., description="Role mới của user")

@router.post("/user/role", response_model=UpdateRoleResponse)
async def update_role(request: UpdateRoleRequest):
    try:
        result = update_role_service(
            requester_id=request.requester_id,
            target_user_id=request.target_user_id,
            new_role=request.new_role
        )
        return UpdateRoleResponse(
            user_id=result['user_id'],
            role=result['role']
        )
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
